//refAssemblies: TCAdmin.Monitor.SDK.dll
using System;
using System.IO;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Linux: the Steam download can lose the executable bit of the server binary, and the Steam game server only loads
// the 64-bit steamclient.so from ~/.steam/sdk64 (the service root is the home directory; without it the server stops
// at "Steam game server failed to initialize"). Eco ships that library in linux64. The script runs as root in a
// folder the service user owns, so it never follows a symbolic link (a planted link would make root change or
// overwrite another file), and it hands what it creates to the service user.
var root = (string)ThisService.RootDirectory;
if (System.OperatingSystem.IsLinux())
{
    var exe = Path.Combine(root, "EcoServer");
    if (IsLink(root) || IsLink(exe))
        throw new Exception("EcoServer is a symbolic link; reinstall the server.");
    if (!File.Exists(exe)) throw new Exception("EcoServer is missing; reinstall the server.");
    var exec = UnixFileMode.UserExecute | UnixFileMode.GroupExecute | UnixFileMode.OtherExecute;
    var mode = File.GetUnixFileMode(exe);
    if ((mode & exec) != exec)
    {
        File.SetUnixFileMode(exe, mode | exec);
        ScriptConsole.WriteLine((object)"Made EcoServer executable.");
    }

    var linux64 = Path.Combine(root, "linux64");
    var source = Path.Combine(linux64, "steamclient.so");
    var steam = Path.Combine(root, ".steam");
    var sdk = Path.Combine(steam, "sdk64");
    var target = Path.Combine(sdk, "steamclient.so");
    if (IsLink(linux64) || IsLink(source) || IsLink(steam) || IsLink(sdk) || IsLink(target))
        throw new Exception("linux64 or .steam contains a symbolic link; remove it or reinstall the server.");
    if (!File.Exists(source)) throw new Exception("linux64/steamclient.so is missing; reinstall the server.");
    if (!File.Exists(target) || new FileInfo(target).Length != new FileInfo(source).Length)
    {
        var credential = ServiceManagerService.GetServiceCredential(ThisService.ServiceId);
        foreach (var dir in new[] { steam, sdk })
        {
            if (Directory.Exists(dir)) continue;
            Directory.CreateDirectory(dir);
            Globals.OperatingSystem.SetDirectoryOwner(dir, credential.Domain, credential.UserName, false);
        }
        File.Copy(source, target, true);
        Globals.OperatingSystem.SetFileOwner(target, credential.UserName);
        ScriptConsole.WriteLine((object)"Copied linux64/steamclient.so to .steam/sdk64 for the Steam game server.");
    }
}

bool IsLink(string path)
{
    // LinkTarget also sees a dangling link (File.Exists is false for one).
    var info = new FileInfo(path);
    if (info.LinkTarget != null) return true;
    if (!info.Exists && !Directory.Exists(path)) return false;
    return (File.GetAttributes(path) & FileAttributes.ReparsePoint) != 0;
}

//refAssemblies: TCAdmin.Web.Shared.dll, System.Net.Http.dll, System.Net.Primitives.dll, System.Text.Json.dll
using System;
using System.Net.Http;
using System.Text.Json;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Eco has no Steam (A2S) query: its web server (the service's QueryPort, Network.eco WebServerPort) answers GET /info
// with the server name, the online players and the world. The request needs no login and does not show in the console
// (only in the web server's request log, Logs/Microsoft.AspNetCore.Hosting.Diagnostics).
string address = Convert.ToString(Dynamic.Address);
if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
int port = ThisService.QueryPort;

string Str(JsonElement root, string name)
{
    return root.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : string.Empty;
}

int Int(JsonElement root, string name)
{
    return root.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.Number && v.TryGetInt32(out var i) ? i : 0;
}

try
{
    string body;
    using (var http = new HttpClient { Timeout = TimeSpan.FromSeconds(4) })
        body = await http.GetStringAsync("http://" + address + ":" + port + "/info", ThisCancellationToken);
    using (var doc = JsonDocument.Parse(body))
    {
        var root = doc.RootElement;
        // The name can carry Eco's rich-text tags (<color=...>): strip them for the panel.
        var name = System.Text.RegularExpressions.Regex.Replace(Str(root, "Description"), "<[^>]*>", string.Empty).Trim();
        Globals.ReturnValue = new GameQueryResponse
        {
            Success = true,
            Status = "online",
            Protocol = "custom_script",
            Address = address,
            Hostname = address + ":" + ThisService.GamePort,
            Name = string.IsNullOrWhiteSpace(name) ? ThisService.Name : name,
            GameType = "Eco",
            Map = Str(root, "WorldSize"),
            NumPlayers = Int(root, "OnlinePlayers"),
            MaxPlayers = ThisService.Slots,
            NumSpectators = 0,
            MaxSpectators = 0,
            Retries = 0
        };
    }
}
catch (Exception ex)
{
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", ex.Message);
}

//refAssemblies: System.Text.Json.dll
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Text.Json.Nodes;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Eco installs the mod.io mods listed in Configs/ModKit.eco (SubscribedMods) itself, but removing an id from the list
// only stops the server following it: the files stay and the mod keeps loading. Before each start, uninstall every
// mod the server installed from mod.io (Mods/UserCode/mod.io/<mod>/manifest.json lists its files) that is no longer
// listed, pinned or needed by another mod. Skipped when the server follows a mod.io collection or account
// subscriptions (those mods are not in the list). A listed mod whose files were deleted by hand gets its stale install
// record removed so the server installs it again. Never follows symbolic links or junctions, never leaves Mods (and never touches Mods/__core__).
var root = Path.GetFullPath((string)ThisService.RootDirectory);
var mods = Path.Combine(root, "Mods");
var userCode = Path.Combine(mods, "UserCode");
var core = Path.Combine(mods, "__core__");
var records = Path.Combine(userCode, "mod.io");
var modKit = Path.Combine(root, "Configs", "ModKit.eco");

bool IsLink(string path)
{
    // LinkTarget also sees a dangling link (File.Exists is false for one) and Windows junctions.
    var info = new FileInfo(path);
    if (info.LinkTarget != null) return true;
    if (!info.Exists && !Directory.Exists(path)) return false;
    return (File.GetAttributes(path) & FileAttributes.ReparsePoint) != 0;
}

if (!Directory.Exists(records) || !File.Exists(modKit)) return;
// The script runs as root on Linux in folders the service user owns: refuse linked folders/files outright.
if (IsLink(root) || IsLink(mods) || IsLink(userCode) || IsLink(records) || IsLink(Path.GetDirectoryName(modKit)) || IsLink(modKit)) return;

// True when the path is inside Mods (never Mods/__core__, never Mods/UserCode itself) and no folder between it and the
// service root is a link.
bool Safe(string full)
{
    var sep = Path.DirectorySeparatorChar.ToString();
    if (!full.StartsWith(mods + sep, StringComparison.OrdinalIgnoreCase)) return false;
    if (full.StartsWith(core + sep, StringComparison.OrdinalIgnoreCase) || string.Equals(full, core, StringComparison.OrdinalIgnoreCase)) return false;
    if (string.Equals(full, userCode, StringComparison.OrdinalIgnoreCase)) return false;
    for (var p = full; p != null && p.Length > root.Length; p = Path.GetDirectoryName(p))
        if (IsLink(p)) return false;
    return true;
}

HashSet<long> Ids(JsonNode config, string key)
{
    var set = new HashSet<long>();
    var values = config?[key]?["System.Int32"]?["$values"] as JsonArray;
    if (values != null)
        foreach (var v in values)
            if (v != null && long.TryParse(v.ToString(), out var id)) set.Add(id);
    return set;
}

JsonNode kit;
try { kit = JsonNode.Parse(File.ReadAllText(modKit)); }
catch (Exception ex) { ScriptConsole.WriteLine((object)("mod.io cleanup skipped: Configs/ModKit.eco is not valid JSON (" + ex.Message + ").")); return; }
var follows = (kit?["TrackModIoSubscriptions"]?.GetValue<bool>() ?? false) || Ids(kit, "TrackedCollections").Count > 0;
if (follows) return;
var keep = Ids(kit, "SubscribedMods");
keep.UnionWith(Ids(kit, "PinnedMods"));

var updatesPath = Path.Combine(records, "updates.json");
JsonNode updates = null;
if (File.Exists(updatesPath) && !IsLink(updatesPath))
{
    try { updates = JsonNode.Parse(File.ReadAllText(updatesPath)); } catch { updates = null; }
}
var updateMods = updates?["Mods"] as JsonObject;

var changed = false;
var downloads = Path.Combine(records, "Downloads");
// Forgets the server's install record of a mod (and its downloaded package), so the server sees it as not installed.
void DropRecord(string dir, string manifestPath, long id)
{
    File.Delete(manifestPath);
    if (!Directory.EnumerateFileSystemEntries(dir).Any()) Directory.Delete(dir);
    if (Directory.Exists(downloads) && !IsLink(downloads))
        foreach (var zip in Directory.GetFiles(downloads, Path.GetFileName(dir) + "_*.zip"))
            if (!IsLink(zip)) File.Delete(zip);
    if (updateMods != null && updateMods.Remove(id.ToString())) changed = true;
}

foreach (var dir in Directory.GetDirectories(records))
{
    var manifestPath = Path.Combine(dir, "manifest.json");
    if (IsLink(dir) || !File.Exists(manifestPath) || IsLink(manifestPath)) continue;
    JsonNode manifest;
    try { manifest = JsonNode.Parse(File.ReadAllText(manifestPath)); } catch { continue; }
    long id;
    if (!long.TryParse(manifest?["mod"]?["id"]?.ToString(), out id)) continue;
    var name = manifest?["mod"]?["name"]?.ToString() ?? id.ToString();
    var files = new List<string>();
    foreach (var f in (manifest?["files"] as JsonArray) ?? new JsonArray())
    {
        var rel = f?.ToString();
        if (string.IsNullOrEmpty(rel)) continue;
        var full = Path.GetFullPath(Path.Combine(root, rel.Replace('/', Path.DirectorySeparatorChar)));
        if (Safe(full)) files.Add(full);
    }

    if (keep.Contains(id))
    {
        // A listed mod whose files were deleted by hand keeps its install record, and the server then never installs
        // it again. Forget the record so the server reinstalls it (Install mode) or /mods sync does.
        if (files.Count > 0 && files.Any(x => !File.Exists(x)))
        {
            DropRecord(dir, manifestPath, id);
            ScriptConsole.WriteLine((object)("The mod.io mod " + id + " (" + name + ") is missing files: the server will install it again."));
        }
        continue;
    }
    var entry = updateMods?[id.ToString()];
    if (entry?["RequiredBy"] is JsonArray requiredBy && requiredBy.Count > 0) continue;

    var removed = 0;
    var folders = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    foreach (var full in files)
    {
        if (!File.Exists(full)) continue;
        File.Delete(full);
        removed++;
        folders.Add(Path.GetDirectoryName(full));
    }
    // Remove the folders the mod leaves empty, deepest first, up to Mods/UserCode (kept).
    foreach (var folder in folders.OrderByDescending(x => x.Length))
        for (var p = folder; p != null && Safe(p) && Directory.Exists(p) && !Directory.EnumerateFileSystemEntries(p).Any(); p = Path.GetDirectoryName(p))
            Directory.Delete(p);
    DropRecord(dir, manifestPath, id);
    ScriptConsole.WriteLine((object)("Uninstalled the mod.io mod " + id + " (" + name + "): no longer in the Mods list of Configs/ModKit.eco. " + removed + " file(s) removed."));
}
if (changed)
    File.WriteAllText(updatesPath, updates.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));
